/**
 * Shader of the scanlines.
 *
 * ## The mathematical idea
 *
 * The whole cathode-ray screen fits into periodic functions of the vertical
 * axis alone: the lines are a high-frequency sine of y, the rolling bar is the
 * fractional part of y offset by time, and the grain is a hash of the pixel
 * replayed in time steps — discrete, because one draw per frame would flicker
 * instead of granulating. A vignette closes the whole thing.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background of the tube.
 * - `uColorB` — the hue of the phosphor.
 * - `uColorC` — the hue of the rolling bar.
 * - `uSpeed` — speed of the bar.
 * - `uLines` — number of lines across the height.
 * - `uFlicker` — share of the animated grain.
 */
export const SCANLINES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uLines;
uniform float uFlicker;

// Pseudo-random number: projection onto an arbitrary direction, amplified sine,
// fractional part.
float tubeHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float t = uTime;

  // The lines: a sine of y, squared to hollow out the gaps between lines
  // without hardening the crests.
  float line = 0.5 + 0.5 * sin(vUv.y * max(uLines, 1.0) * 6.28318);
  line = 0.35 + 0.65 * line * line;

  // The rolling bar: the fractional part of y offset by time loops the descent
  // round with no test at all.
  float roll = fract(vUv.y + t * uSpeed * 0.2);
  float bar = smoothstep(0.0, 0.12, roll) * smoothstep(0.30, 0.12, roll);

  // The grain: a hash of the pixel replayed in time steps. Discrete — the step
  // holds the image for a few hundredths — because one draw per frame flickers
  // instead of granulating.
  float tick = floor(t * 18.0);
  float grain = (tubeHash(floor(vUv * uResolution * 0.5) + tick) - 0.5) * uFlicker * 0.35;

  vec3 colour = mix(uColorA, uColorB, line * (0.75 + grain));
  colour = mix(colour, uColorC, bar * 0.30);

  // Vignette: the corners of a tube are darker than its centre.
  vec2 offset = (vUv - 0.5) * vec2(aspect, 1.0);
  colour *= 1.0 - smoothstep(0.35, 0.85, length(offset)) * 0.55;

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Scanlines: a cathode-ray screen, its rolling bar and its grain.
 *
 * ## The principle
 *
 * Everything fits into periodic functions of the vertical axis alone: a sine for the lines, a fractional part offset by time for the bar.
 *
 * The grain is replayed in time steps, never per frame — one draw per frame flickers instead of granulating.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its
 * fallback. Reading the tokens, converting them to floats and re-reading them
 * when the theme changes all come from the engine — copying that here would
 * leave as many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { SCANLINES_FRAGMENT } from './scanlines.shader.js'

/** What the escape hatch receives. */
export interface ScanlinesControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface ScanlinesOwnProps {
  /** Speed of the rolling bar. @defaultValue 0.5 */
  speed?: number
  /** Number of lines across the height. @defaultValue 90 */
  lines?: number
  /** Share of the animated grain. @defaultValue 0.4 */
  flicker?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<ScanlinesControls>
}

/** All props. */
export type ScanlinesProps = Customisable<ScanlinesOwnProps>

/** Tokens used by default: the tube, the phosphor, the bar. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-green-400',
  '--o-palette-emerald-200',
] as const

/** Default fallback: a frozen tint, in the same tones. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Scanlines.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Scanlines className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Scanlines({
  speed = 0.5,
  lines = 90,
  flicker = 0.4,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: ScanlinesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: SCANLINES_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uLines: lines, uFlicker: flicker },
    name: 'scanlines',
    // The grain is the only value recomputed at every time step: on a screen
    // whose density has been capped, it is also what swarms the most. It is
    // therefore the bounded setting.
    degrade: (quality) => ({
      uFlicker: quality === 'low' ? Math.min(flicker, 0.15) : flicker,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
